<template><section ref="historyPanel" class="model-tool-section"><ModelSourceDialog ref="sourceDialog" :language="language" :busy="store.busy" :working="store.working" v-model:scale="scale" :notice="sourceNotice" @import="importMesh" @template="chooseTemplate"/><div class="source-actions"><button class="primary" :disabled="store.busy" @click="importMesh">{{zh?'导入三角 OBJ / GLB':localize('Import triangulated OBJ / GLB')}}</button><button :class="{active:showSpecies}" :aria-expanded="showSpecies" @click="showSpecies=!showSpecies;showBody=false">{{zh?'物种全身模板':localize('Full-body species templates')}}</button></div><p class="model-dimensions">{{zh?'整体包围框（含手臂、尾巴与翼）':localize('Whole bounding box (includes arms, tail and wings)')}} {{modelDimensions.map(n=>n.toFixed(2)).join(' × ')}} mm ({{modelDimensions.map(n=>(n/10).toFixed(2)).join(' × ')}} cm)</p><details v-if="surface" class="model-size-controls" open><summary>{{zh?'调整模型尺寸':localize('Resize model')}}</summary><label class="body-constraint"><input v-model="bodyConstrained" type="checkbox" :disabled="!canConstrainBody" :aria-label="zh?'遵循身体尺寸约束':localize('Follow body measurement constraints')">{{zh?'遵循身体尺寸约束':localize('Follow body measurement constraints')}}</label><template v-if="bodyConstrained&&canConstrainBody"><p v-if="(surface?.template?.parameters.bodyMode??'costume')==='costume'">{{zh?'按头耳至足底身高和躯干围度重新生成，按物种身体配方校验比例与左右对称；胸、腰、臀与颈围不包含手臂、尾巴或翼。下方是包含填充与层厚的实际目标，不是包围框宽深。':localize('Regenerate from head-and-ear-to-sole height and anatomical torso girths, validating species proportions and paired limbs. Girths exclude arms, tail and wings; targets include padding and layers, not bounding-box width/depth.')}}</p><p v-else>{{zh?'下方目标是当前生成模型参考面的高度与围度，包含此模式已生效的填充与层厚，不是原始 DTD 测量。修改穿戴者尺寸或填充厚度，请使用下方模板参数重新生成。':localize('These targets describe the generated reference surface, including active padding and layers, not the original DTD measurements. Edit wearer dimensions or padding in the template form below and regenerate.')}}</p><div class="dimension-grid body-targets"><label v-for="(value,key) in bodyTargets" :key="key">{{modelMeasurementLabel(key)}} mm<input v-decimal v-model.number="bodyTargets[key]" type="number" min=".01" step=".01" :aria-label="'Body '+key+' mm'"></label></div><button class="primary" :disabled="store.busy||!bodyTargetsValid" @click="applyBodyTargets">{{zh?'应用身体测量':localize('Apply body measurements')}}</button></template><template v-else><p>{{zh?'自由缩放设置整个模型的 X 宽、Y 高与 Z 深，包含所有附肢；等比缩放保持三轴比例。内置模型自由缩放后转为通用网格，原身体配方与测量报告不再适用，花纹随网格保留，需重新裁切。':localize('Free resizing changes the whole X/Y/Z bounds, including appendages. Uniform scaling keeps axis proportions. A resized built-in becomes a generic mesh; its body recipe and measurements no longer apply. Paint follows the mesh; regenerate cuts.')}}</p><p v-if="!canConstrainBody">{{zh?'此模型没有有效的内置身体配方，不能推断胸腰臀测量；可自由缩放或使用下方模板。':localize('This mesh has no valid built-in body recipe. Anatomical girths cannot be inferred; resize freely or choose a template below.')}}</p><label>{{zh?'调整方式':localize('Resize mode')}}<select v-model="sizeMode" aria-label="Model resize mode"><option value="dimensions">{{zh?'宽 × 高 × 深':localize('Width × height × depth')}}</option><option value="uniform">{{zh?'等比缩放':localize('Uniform scale')}}</option></select></label><label v-if="sizeMode==='uniform'">{{zh?'倍率':localize('Scale factor')}}<input v-decimal v-model.number="uniformScale" type="number" min=".01" max="100000" step=".01" aria-label="Model uniform scale"></label><div v-else class="dimension-grid"><label v-for="axis in (['width','height','depth'] as const)" :key="axis">{{zh?({width:'整体宽度 X',height:'整体高度 Y',depth:'整体深度 Z'}[axis]):localize(axis)}} mm<input v-decimal v-model.number="requestedSize[axis]" type="number" :min="dimensions?.[axis]===0?0:.01" max="100000" step=".01" :disabled="dimensions?.[axis]===0" :aria-label="'Model '+axis+' mm'"></label></div><small v-if="!sizeValid" role="alert">{{zh?'请输入有效的正数尺寸或缩放倍率；平面模型的零厚度保持为 0。':localize('Enter positive finite sizes or a scale factor. Planar axes remain at zero.')}}</small><button class="primary" :disabled="store.busy||!sizeValid" @click="resizeModel">{{zh?'应用模型尺寸':localize('Apply model size')}}</button></template><p v-if="sizeNotice" role="status">{{sizeNotice}}</p></details><details class="tool-details"><summary>{{zh?'导入与导出选项':localize('Import & export options')}}</summary><p>{{zh?'OBJ 无内置单位：原坐标为 mm 时比例 1，为 cm 时填 10。GLB 自动由米转换为 mm，通常额外倍率保持 1。导入后核对右侧模型尺寸。':localize('OBJ has no encoded unit: use 1 for mm, 10 for cm. GLB metres convert to mm automatically; keep the extra scale at 1. Verify model dimensions after import.')}}</p><label>{{zh?'导入比例（OBJ 每单位 mm；GLB 额外倍率）':localize('Import scale (OBJ mm per unit; GLB extra multiplier)')}}<input v-model.number="scale" type="number" min=".00001" step=".1"></label><button :disabled="store.busy||!surface" @click="exportMesh">{{zh?'导出静态 GLB（米）':localize('Export static GLB (metres)')}}</button></details>
 <p>{{zh?'导入模型或选择模板开始。模板生成会替换当前模型，可撤销。':localize('Import a mesh or choose a template. Generating replaces the model and can be undone.')}}</p>
 <div v-if="showSpecies" ref="speciesForm" class="body-form">
  <label>{{zh?'生成查看模式':localize('Generation view mode')}}<select :value="bodyMode" :disabled="store.busy" :aria-label="zh?'模型生成模式':localize('Model generation mode')" @change="setBodyMode(($event.target as HTMLSelectElement).value as BodyMode)"><option v-for="mode in (['dtd','padded','costume'] as const)" :key="mode" :value="mode">{{bodyModeLabel(mode)}}</option></select></label>
  <p>{{zh?'三种模式沿用同一穿戴者的身体尺寸。切换模式或物种会保留已输入的身高、围度、肩宽和肢长。':localize('All three modes retain the same wearer measurements. Switching mode or species preserves entered height, girths, shoulder width and limb lengths.')}}</p>
  <p v-if="bodyMode!=='costume'">{{zh?'身体围度填写穿戴者的 DTD 测量，身高不包含兽装耳朵。臀部、大腿和小腿的填充值表示向外增加的厚度，不是围度增量。':localize('Enter wearer DTD girths and height without costume ears. Hip, thigh and calf padding values are outward thicknesses, not added circumference.')}}</p>
  <p v-if="bodyMode==='dtd'" class="body-mode-note">{{zh?'DTD 人体基体按真人身高比例生成头部，不附加兽头、耳尾或兽爪，也不叠加填充与参考层厚。填充数值会保留，切回一体填充模式后生效。':localize('The DTD base uses a human head proportion and excludes animal head features, ears, tail, paws, padding and reference layers. Padding values are retained for the padded mode.')}}</p>
  <p v-else-if="bodyMode==='padded'" class="body-mode-note">{{zh?'一体填充外形在 DTD 身体尺寸上增加局部填充，生成连续的身体外形；兽头、耳尾和兽爪另在兽装外形模式设置。':localize('The integrated padded body adds local padding to the DTD measurements to form a continuous body. Animal head features, ears, tail and paws are configured in costume mode.')}}</p>
  <p v-else class="body-mode-note">{{zh?'兽装外形包含头耳尾、爪和旧版全局填充参数。未记录生成模式的旧项目按此模式读取，已有尺寸不会自动换算。':localize('Costume mode includes head, ears, tail, claws and legacy global padding. Older recipes without a mode open here; stored dimensions are not converted.')}}</p>
  <label>{{zh?'材料有效补偿':localize('Material compensation')}}<select v-model="layerMaterial" :disabled="store.busy||bodyMode==='dtd'"><option value="">—</option><option v-for="m in store.data.project?.materials??[]" :key="m.id" :value="m.id">{{m.name}} / {{m.compensationMm}} mm</option></select></label>
  <button :disabled="store.busy||bodyMode==='dtd'||!layerMaterial" @click="useMaterialLayer">{{zh?'将补偿填入参考层厚（生成后生效）':localize('Copy compensation to layer (applies on generation)')}}</button>
  <label>{{zh?'物种':localize('Species')}}<select ref="speciesSelect" :value="speciesParams.species" :disabled="store.busy" @change="setSpecies(($event.target as HTMLSelectElement).value as SpeciesParams['species'])"><option v-for="species in ['canine','feline','rabbit','bear','deer','dragon']" :key="species" :value="species">{{zh?speciesNames[species]:localize(species)}}</option></select></label>
  <label v-if="bodyMode==='costume'">{{zh?'腿型':localize('Leg posture')}}<select v-model="speciesParams.legType" :disabled="store.busy"><option value="plantigrade">{{zh?'植行腿':localize('Plantigrade')}}</option><option value="digitigrade">{{zh?'趾行腿':localize('Digitigrade')}}</option></select></label>
  <details v-for="(group,index) in speciesGroups" :key="group.id" class="species-group" :open="index===0||group.id==='padding'"><summary>{{zh?group.zh:localize(group.en)}}</summary><div class="dimension-grid"><label v-for="key in group.keys" :key="key">{{zh?speciesLabels[key]:localize(speciesEnglishLabels[key]??key.replace(/([A-Z])/g,' $1'))}}<input v-model.number="speciesParams[key]" v-decimal type="number" :min="speciesRanges[key][0]" :max="speciesRanges[key][1]" :step="key.includes('Rad')||key==='tailCurvature'?.01:1" :disabled="store.busy||bodyMode==='dtd'&&group.id==='padding'"></label></div></details>
  <p v-if="!speciesValid" role="alert">{{bodyMode==='costume'?(zh?'请检查尺寸范围与比例：总高减去耳高、头长、腿长及 70 mm 颈部后，躯干至少保留 150 mm；尾尖围不得大于尾根围。':localize('Check ranges and proportions: height minus ears, head, legs and 70 mm neck must leave at least 150 mm torso; tail tip girth cannot exceed its base.')):(zh?'请检查人体尺寸范围、身高和肢长比例，以及 0–200 mm 的局部填充厚度。':localize('Check wearer measurement ranges, height and limb proportions, and local padding thicknesses from 0 to 200 mm.'))}}</p>
  <button class="primary" :disabled="store.busy||!speciesValid" @click="generateTemplate">{{zh?'生成 / 更新物种模板':localize('Generate / update species template')}}</button>
  <p class="body-mode-note">{{zh?'生成成功后自动保存到当前项目的模型库。可分别生成 DTD 人体基体、一体填充外形与兽装外形，再从模型库切换查看。这里预览当前活动模型。':localize('Each generated model is saved in this project’s model library. Generate the DTD base, padded body and costume separately, then switch between them in the library. The preview shows the active model.')}}</p>
 </div>
 <details v-if="surface?.template" class="tool-details"><summary>{{zh?'拼合与测量报告':localize('Assembly & measurements')}}</summary><button :disabled="store.busy||!!surface.assembly" @click="assemble">{{zh?'拼合为连续网格（可撤销）':localize('Assemble continuous shell (undoable)')}}</button><p>{{zh?'以下是部位参考面的尺寸；连续网格身高与躯干围度另列。':localize('Part reference dimensions below; continuous mesh height and torso girths are listed separately.')}}</p><strong>{{bodyModeLabel(surface.template.parameters.bodyMode??'costume')}}<template v-if="(surface.template.parameters.bodyMode??'costume')==='costume'"> · {{zh?(speciesNames[surface.template.parameters.species]+' · '+(surface.template.parameters.legType==='digitigrade'?'趾行腿':'植行腿')):surface.template.id}}</template> v{{surface.template.version}}</strong> · {{surface.template.parts.length}} {{zh?'部件':localize('parts')}}<p>{{surface.template.parts.map(part=>modelPartLabel(part,zh)).join(' · ')}}</p><table><thead><tr><th>{{zh?'测量':localize('Measurement')}}</th><th>{{zh?'目标 mm':localize('Target mm')}}</th><th>{{zh?'实测 mm':localize('Actual mm')}}</th><th>{{zh?'偏差 mm':localize('Δ mm')}}</th></tr></thead><tbody><tr v-for="m in surface.template.measurements" :key="m.name"><td>{{modelMeasurementLabel(m.name)}}</td><td>{{m.targetMm.toFixed(2)}}</td><td>{{m.actualMm.toFixed(2)}}</td><td>{{m.residualMm.toFixed(2)}}</td></tr></tbody></table></details>
 <details v-if="surface?.assembly" class="tool-details"><summary>{{zh?'实体拼合报告':localize('Solid assembly report')}}</summary><strong>{{zh?'实体拼合报告':localize('Solid assembly report')}}</strong> · {{surface.assembly.components}} {{zh?'个连续实体':localize('component')}} · {{surface.assembly.volumeMm3.toFixed(2)}} mm³ · {{zh?'累计简化容差':localize('Cumulative simplification tolerance')}} {{surface.assembly.toleranceMm.toFixed(2)}} mm<p>{{zh?'身高取连续网格整体范围；胸、腰、臀和颈围取用于生成模型的躯干截面，排除手臂、翼和尾部。':localize('Height measures the whole continuous mesh. Chest, waist, hip and neck girths measure its torso source sections, excluding arms, wings and tail.')}}</p><table><thead><tr><th>{{zh?'拼合后测量':localize('Assembled measurement')}}</th><th>{{zh?'目标 mm':localize('Target mm')}}</th><th>{{zh?'实测 mm':localize('Actual mm')}}</th><th>{{zh?'偏差 mm':localize('Δ mm')}}</th></tr></thead><tbody><tr v-for="m in surface.assembly.measurements" :key="m.name"><td>{{modelMeasurementLabel(m.name)}}</td><td>{{m.targetMm.toFixed(2)}}</td><td>{{m.actualMm.toFixed(2)}}</td><td>{{m.residualMm.toFixed(2)}}</td></tr></tbody></table></details>
 <div v-if="showBody&&advanced" class="body-form"><p>{{zh?'原创固定拓扑躯干曲面，用于测量、填充和展开实验；尚非完整犬猫身体模板。无填充时离散截面周长匹配输入围度。':localize('Original fixed-topology torso surface for measurement, padding and unwrap experiments; not a complete canine/feline template. Without padding, discrete ring girths match inputs.')}}</p><label v-for="(value,key) in params" :key="key">{{localize(names[key][zh?0:1])}}<input v-model.number="params[key]" v-decimal type="number" :step="key==='depthRatio'?.01:1"></label><button :disabled="store.busy||!bodyValid" @click="generate">{{zh?'生成 / 更新躯干':localize('Generate / update torso')}}</button></div>

<ModelEditControls :language="language"/><CustomTemplatePanel :language="language"/><MeshEditPanel :language="language"/><details v-if="advanced" class="tool-details"><summary>{{zh?'参数躯干（实验）':localize('Parametric torso (experimental)')}}</summary><button @click="showBody=!showBody">{{zh?'设置躯干参数':localize('Set torso parameters')}}</button></details></section></template>

<script setup lang="ts">
import {localize} from './localization';

import {computed,inject,nextTick,ref,watch} from 'vue';
import {surfaceDimensions,type ModelDimensions} from '../../../packages/surface/dimensions';
import {validSpeciesParameters,validBodyParameters,speciesRanges} from '../../../packages/body/parameter-validation';
import ModelSourceDialog from './ModelSourceDialog.vue';
import {useSession} from './store';
import {useDraftHistory} from './modules/useDraftHistory';
import CustomTemplatePanel from './CustomTemplatePanel.vue';
import MeshEditPanel from './MeshEditPanel.vue';
import ModelEditControls from './ModelEditControls.vue';
import {speciesDefaults} from '../../../packages/body/defaults';
import {vDecimal} from './modules/decimal-input';
import {measurementLabel,modelPartLabel} from './modules/model-labels';
import type {SpeciesParams,BodyParams} from '../../../packages/schema/index';
const props=defineProps<{language:'zh'|'en'}>(),advanced=inject('advancedMode',ref(false)),store=useSession(),zh=computed(()=>props.language==='zh'),surface=computed(()=>store.data.project?.surface),scale=ref(1),showBody=ref(false);
const speciesNames:Record<string,string>={canine:'犬科',feline:'猫科',rabbit:'兔',bear:'熊',deer:'鹿',dragon:'龙'};
const speciesLabels:Record<string,string>={heightMm:'总身高 mm',neckGirthMm:'颈围 mm',chestGirthMm:'胸围 mm',waistGirthMm:'腰围 mm',hipGirthMm:'臀围 mm',shoulderWidthMm:'肩宽 mm',armLengthMm:'臂长 mm',legLengthMm:'腿长 mm',headWidthMm:'头宽 mm',headLengthMm:'头部高度 mm',snoutLengthMm:'口鼻长度 mm',snoutWidthMm:'口鼻宽度 mm',earHeightMm:'耳高 mm',earWidthMm:'耳宽 mm',earAngleRad:'耳外倾角 rad',tailLengthMm:'尾中心线长 mm',tailBaseGirthMm:'尾根围度 mm',tailTipGirthMm:'尾尖围度 mm',tailCurvature:'尾曲率比例',upperArmGirthMm:'上臂围 mm',forearmGirthMm:'前臂围 mm',thighGirthMm:'大腿围 mm',shinGirthMm:'小腿围 mm',pawLengthMm:'手爪长度 mm',pawWidthMm:'手足宽度 mm',footLengthMm:'足长 mm',clawLengthMm:'爪长 mm',paddingMm:'全局填充 mm',hipPaddingMm:'臀部外扩厚度 mm',thighPaddingMm:'大腿外扩厚度 mm',calfPaddingMm:'小腿外扩厚度 mm',layerMm:'参考面层厚 mm'};
const showSpecies=ref(false),speciesParams=ref<SpeciesParams>(speciesDefaults('canine','padded'));
type BodyMode=NonNullable<SpeciesParams['bodyMode']>;
const bodyMode=computed<BodyMode>(()=>speciesParams.value.bodyMode??'costume');
function bodyModeLabel(mode:BodyMode){return ({dtd:zh.value?'DTD 人体基体':localize('DTD wearer base'),padded:zh.value?'一体填充外形':localize('Integrated padded body'),costume:zh.value?'兽装外形':localize('Costume exterior')})[mode];}
function modelMeasurementLabel(name:string){return name==='height'&&(surface.value?.template?.parameters.bodyMode??'costume')!=='costume'?(zh.value?'模型参考高度':localize('Model reference height')):measurementLabel(name,zh.value);}
const speciesAppearanceKeys=['legType','headWidthMm','headLengthMm','snoutLengthMm','snoutWidthMm','earHeightMm','earWidthMm','earAngleRad','tailLengthMm','tailBaseGirthMm','tailTipGirthMm','tailCurvature','pawLengthMm','pawWidthMm','clawLengthMm'] as const;
const localPaddingKeys=['hipPaddingMm','thighPaddingMm','calfPaddingMm'] as const;
const speciesEnglishLabels:Partial<Record<keyof typeof speciesRanges,string>>={hipPaddingMm:'Hip padding thickness mm',thighPaddingMm:'Thigh padding thickness mm',calfPaddingMm:'Calf padding thickness mm'};
const speciesGroups=computed<{id:string;zh:string;en:string;keys:(keyof typeof speciesRanges)[]}[]>(()=>[
 {id:'body',zh:bodyMode.value==='costume'?'身体尺寸':'穿戴者 DTD 身体尺寸',en:bodyMode.value==='costume'?'Body dimensions':'Wearer DTD body dimensions',keys:['heightMm','neckGirthMm','chestGirthMm','waistGirthMm','hipGirthMm','shoulderWidthMm']},
 {id:'limbs',zh:bodyMode.value==='costume'?'四肢与手足':'穿戴者四肢尺寸',en:bodyMode.value==='costume'?'Limbs & paws':'Wearer limb dimensions',keys:['armLengthMm','legLengthMm','upperArmGirthMm','forearmGirthMm','thighGirthMm','shinGirthMm','footLengthMm',...(bodyMode.value==='costume'?['pawLengthMm','pawWidthMm','clawLengthMm'] as const:[])]},
 ...(bodyMode.value==='costume'?[{id:'appearance',zh:'头部与耳尾',en:'Head, ears & tail',keys:['headWidthMm','headLengthMm','snoutLengthMm','snoutWidthMm','earHeightMm','earWidthMm','earAngleRad','tailLengthMm','tailBaseGirthMm','tailTipGirthMm','tailCurvature'] as (keyof typeof speciesRanges)[]}]:[]),
 {id:'padding',zh:bodyMode.value==='costume'?'填充与层厚':'局部填充与层厚',en:bodyMode.value==='costume'?'Padding & layer':'Local padding & layer',keys:bodyMode.value==='costume'?['paddingMm','layerMm']:[...localPaddingKeys,'layerMm']}
]);
const layerMaterial=ref('');
function useMaterialLayer(){if(bodyMode.value==='dtd')return;const m=store.data.project?.materials?.find(m=>m.id===layerMaterial.value);if(m)speciesParams.value.layerMm=m.compensationMm;}
function setSpecies(species:SpeciesParams['species']){const defaults=speciesDefaults(species,bodyMode.value);speciesParams.value={...speciesParams.value,species,...Object.fromEntries(speciesAppearanceKeys.map(key=>[key,defaults[key]]))};}
function setBodyMode(mode:BodyMode){
 speciesParams.value.bodyMode=mode;
 if(mode==='costume')return;
 const defaults=speciesDefaults(speciesParams.value.species,mode);
 for(const key of localPaddingKeys)speciesParams.value[key]??=defaults[key]??0;
 for(const key of speciesAppearanceKeys){
  if(key==='legType')continue;
  const value=speciesParams.value[key],[min,max]=speciesRanges[key];
  if(!Number.isFinite(value)||value<min||value>max)speciesParams.value[key]=defaults[key];
 }
 if(speciesParams.value.tailTipGirthMm>speciesParams.value.tailBaseGirthMm){speciesParams.value.tailBaseGirthMm=defaults.tailBaseGirthMm;speciesParams.value.tailTipGirthMm=defaults.tailTipGirthMm;}
}
async function assemble(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.assembleSpecies(p.id,p.revision));}
const speciesValid=computed(()=>validSpeciesParameters(speciesParams.value));
const bodyValid=computed(()=>validBodyParameters(params.value));
async function generateTemplate(){const p=store.data.project;if(p&&speciesValid.value)await store.run(()=>window.fpcad.generateSpecies(p.id,p.revision,JSON.parse(JSON.stringify(speciesParams.value))));}
const params=ref<BodyParams>({heightMm:600,neckGirthMm:500,chestGirthMm:1100,waistGirthMm:900,hipGirthMm:1000,depthRatio:.7,chestPaddingMm:0,waistPaddingMm:0,hipPaddingMm:0,layerMm:0});
const names:Record<keyof BodyParams,[string,string]>={heightMm:['躯干高度 mm','Torso height mm'],neckGirthMm:['颈围 mm','Neck girth mm'],chestGirthMm:['胸围 mm','Chest girth mm'],waistGirthMm:['腰围 mm','Waist girth mm'],hipGirthMm:['臀围 mm','Hip girth mm'],depthRatio:['前后深度 / 左右宽度','Depth / width ratio'],chestPaddingMm:['胸部填充 mm','Chest padding mm'],waistPaddingMm:['腰部填充 mm','Waist padding mm'],hipPaddingMm:['臀部填充 mm','Hip padding mm'],layerMm:['制造参考面层厚 mm','Manufacturing surface layer mm']};
async function exportMesh(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.exportSurface(p.id,p.revision));}
async function importPattern(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.importPattern(p.id,p.revision,scale.value));}
const sourceDialog=ref<InstanceType<typeof ModelSourceDialog>>(),sourceNotice=ref(''),speciesForm=ref<HTMLElement>(),speciesSelect=ref<HTMLSelectElement>();
function openSource(){if(store.busy||!store.data.project)return;sourceNotice.value='';sourceDialog.value?.open();}
async function chooseTemplate(){if(store.busy)return;sourceDialog.value?.close();showSpecies.value=true;showBody.value=false;await nextTick();speciesForm.value?.scrollIntoView({block:'start'});speciesSelect.value?.focus({preventScroll:true});}
async function importMesh(){const p=store.data.project;if(!p||store.busy)return;sourceNotice.value='';const imported=await store.run(()=>window.fpcad.importSurface(p.id,p.revision,scale.value));if(imported){await nextTick();sourceDialog.value?.close();}else sourceNotice.value=store.error?(zh.value?'导入失败：':localize('Import failed: '))+store.error:(zh.value?'未选择文件。可以重新导入或使用内置模板。':localize('No file selected. Try again or use a built-in template.'));}
defineExpose({openSource});
async function generate(){const p=store.data.project;if(p&&bodyValid.value)await store.run(()=>window.fpcad.generateBody(p.id,p.revision,JSON.parse(JSON.stringify(params.value))));}

const dimensions=computed(()=>surface.value?surfaceDimensions(surface.value):undefined),modelDimensions=computed(()=>dimensions.value?Object.values(dimensions.value):[]);
const sizeMode=ref<'dimensions'|'uniform'>('dimensions'),requestedSize=ref<ModelDimensions>({width:0,height:0,depth:0}),uniformScale=ref(1),sizeNotice=ref('');
const canConstrainBody=computed(()=>surface.value?.source==='species-template-1'&&!!surface.value.template),bodyConstrained=ref(false),bodyTargets=ref<Record<string,number>>({});
const historyPanel=ref<HTMLElement>();
const history=useDraftHistory(()=>({scale:scale.value,species:speciesParams.value,body:params.value,size:requestedSize.value,uniform:uniformScale.value,targets:bodyTargets.value,constrained:bodyConstrained.value,mode:sizeMode.value,material:layerMaterial.value}),v=>{scale.value=v.scale;speciesParams.value=v.species;params.value=v.body;requestedSize.value=v.size;uniformScale.value=v.uniform;bodyTargets.value=v.targets;bodyConstrained.value=v.constrained;sizeMode.value=v.mode;layerMaterial.value=v.material;},()=>!!historyPanel.value?.getClientRects().length,()=>store.busy);
watch(()=>JSON.stringify([surface.value?.id,surface.value?.source]),()=>{history.reset(()=>{bodyConstrained.value=canConstrainBody.value;});},{immediate:true});
watch(()=>JSON.stringify(surface.value?.template?.measurements),()=>{history.reset(()=>{bodyTargets.value=Object.fromEntries((surface.value?.template?.measurements??[]).filter(m=>['height','neckGirth','chestGirth','waistGirth','hipGirth'].includes(m.name)).map(m=>[m.name,m.actualMm]));});},{immediate:true});
const bodyTargetsValid=computed(()=>Object.keys(bodyTargets.value).length===5&&Object.values(bodyTargets.value).every(v=>Number.isFinite(v)&&v>0));
async function applyBodyTargets(){const p=store.data.project;if(!p||!canConstrainBody.value||!bodyConstrained.value||!bodyTargetsValid.value||store.busy)return;sizeNotice.value='';if(await store.run(()=>window.fpcad.fitSpecies(p.id,p.revision,JSON.parse(JSON.stringify(bodyTargets.value)))))sizeNotice.value=zh.value?'已按身体测量重新生成连续模型。请检查花纹位置并重新裁切。':localize('Continuous model regenerated from body measurements. Review pattern positions and regenerate cuts.');}
watch(()=>JSON.stringify([surface.value?.id,surface.value?.topologyVersion]),()=>{history.reset(()=>{const mesh=surface.value;if(!mesh)return;requestedSize.value=surfaceDimensions(mesh);uniformScale.value=1;if(mesh.template)speciesParams.value=JSON.parse(JSON.stringify(mesh.template.parameters));if(mesh.parameters)params.value={...mesh.parameters};});},{immediate:true});
const sizeValid=computed(()=>sizeMode.value==='uniform'?Number.isFinite(uniformScale.value)&&uniformScale.value>0&&uniformScale.value<=100000:!!dimensions.value&&(['width','height','depth'] as const).every(axis=>Number.isFinite(requestedSize.value[axis])&&requestedSize.value[axis]>=0&&requestedSize.value[axis]<=100000&&(dimensions.value![axis]>1e-10?requestedSize.value[axis]>0:requestedSize.value[axis]===0)));
async function resizeModel(){const p=store.data.project;if(!p||!surface.value||bodyConstrained.value||!sizeValid.value||store.busy)return;sizeNotice.value='';const applied=await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'surface.resize',...(sizeMode.value==='uniform'?{scale:uniformScale.value}:{dimensionsMm:{...requestedSize.value}})}));if(applied)sizeNotice.value=zh.value?'模型尺寸已应用。已贴附花纹随网格保留；请重新裁切。':localize('Model dimensions applied. Attached paint follows the mesh; regenerate cuts.');}

</script>
